import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Process","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/strengthen/process.md","filePath":"en/modules/strengthen/process.md","lastUpdated":0}`),a={name:`en/modules/strengthen/process.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="process" tabindex="-1">Process <a class="header-anchor" href="#process" aria-label="Permalink to “Process”">​</a></h1><p>Strengthening combines target equipment, a recipe, materials, success chance, and failure results. Follow the flow when debugging: first check whether the recipe matches, then materials and costs, and finally PDC writes and presentation refresh.</p><h2 id="standard-flow" tabindex="-1">Standard flow <a class="header-anchor" href="#standard-flow" aria-label="Permalink to “Standard flow”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 1. Player opens the strengthen GUI                           │</span></span>
<span class="line"><span>│ 2. Insert target equipment → read current star and temper    │</span></span>
<span class="line"><span>│ 3. Match an available recipe through the match rules         │</span></span>
<span class="line"><span>│ 4. Validate materials, costs, conditions, and star limit     │</span></span>
<span class="line"><span>│ 5. Compute success rate (base + temper bonus, clamped)       │</span></span>
<span class="line"><span>│ 6. Fire StrengthenPreAttemptEvent (cancellable, rate-writable)│</span></span>
<span class="line"><span>│ 7. Roll the outcome → success / failure                      │</span></span>
<span class="line"><span>│ 8. Rebuild the item and write the strengthen layer           │</span></span>
<span class="line"><span>│ 9. Charge economy costs                                      │</span></span>
<span class="line"><span>│ 10. Fire StrengthenAttemptEvent                              │</span></span>
<span class="line"><span>│ 11. Run that star&#39;s actions.success / actions.failure        │</span></span>
<span class="line"><span>│ 12. Broadcast on first reach of a broadcast star             │</span></span>
<span class="line"><span>│ 13. Settle escrow on the owner thread, refresh GUI/inventory │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="troubleshooting-entry-points" tabindex="-1">Troubleshooting entry points <a class="header-anchor" href="#troubleshooting-entry-points" aria-label="Permalink to “Troubleshooting entry points”">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check first</th></tr></thead><tbody><tr><td>GUI says strengthening is unavailable</td><td>The recipe&#39;s top-level <code>matcher</code> / <code>slot_groups</code>, current star, <code>limits.max_star</code>, and the <code>stars</code> node.</td></tr><tr><td>Insufficient materials after clicking</td><td><code>materials</code>, item sources, amounts, and the player&#39;s actual inventory.</td></tr><tr><td>Currency shortage or charge issues</td><td><code>economy.currencies</code>, the economy provider, and <code>cost_formula</code>.</td></tr><tr><td>Star level does not change</td><td>Whether the strengthen layer was written, and whether failure downgrade or a protection material applied.</td></tr><tr><td>Lore is not refreshed</td><td>Whether CoreLib assembly ran; use <code>/estrengthen refresh</code> if needed.</td></tr></tbody></table><h2 id="stage-details" tabindex="-1">Stage details <a class="header-anchor" href="#stage-details" aria-label="Permalink to “Stage details”">​</a></h2><h3 id="stages-1-2-opening-the-gui-and-item-recognition" tabindex="-1">Stages 1-2: opening the GUI and item recognition <a class="header-anchor" href="#stages-1-2-opening-the-gui-and-item-recognition" aria-label="Permalink to “Stages 1-2: opening the GUI and item recognition”">​</a></h3><p>After opening the strengthen GUI, the player places the target item into the designated slot. The module:</p><ul><li>Reads the item&#39;s current strengthen layer (star, temper level, milestone flags, success/failure counts, branch path).</li><li>Treats an item without a strengthen layer as +0.</li></ul><h3 id="stage-3-recipe-matching" tabindex="-1">Stage 3: recipe matching <a class="header-anchor" href="#stage-3-recipe-matching" aria-label="Permalink to “Stage 3: recipe matching”">​</a></h3><p>Recipes match the target through the following <strong>top-level</strong> fields, combined with AND:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>matcher</code></td><td>General item matcher for non-item-source conditions such as components, PDC, lore, and variables. The top-level item-source condition is expressed by the sibling <code>source_patterns</code>. See <a href="./../corelib/item-matcher.html">Item Matcher</a>.</td></tr><tr><td><code>slot_groups</code></td><td>Coarse slot/equipment type groups (<code>weapon</code>/<code>armor</code>/<code>offhand</code>/<code>generic</code>), not concrete equipment slots.</td></tr><tr><td><code>stats_any</code></td><td>Has any of the given attributes.</td></tr><tr><td><code>source_patterns</code></td><td>Match by item source pattern.</td></tr></tbody></table><p>The old <code>match</code> block is no longer read; see <a href="./recipes.html#migrating-from-match">Recipes</a> for migration.</p><p>The current star must also be below <code>limits.max_star</code>, and the target star must have a matching entry in <code>stars</code>.</p><h3 id="stage-4-validation" tabindex="-1">Stage 4: validation <a class="header-anchor" href="#stage-4-validation" aria-label="Permalink to “Stage 4: validation”">​</a></h3><table tabindex="0"><thead><tr><th>Check</th><th>Failure behavior</th></tr></thead><tbody><tr><td>Required material amounts</td><td>Reports insufficient materials and blocks the attempt.</td></tr><tr><td>Economy balance</td><td>A failed charge returns an uncommitted result.</td></tr><tr><td>Condition check</td><td>Returns <code>strengthen.error.condition_not_met</code> when conditions are unmet.</td></tr><tr><td>Star limit</td><td>Blocks the attempt once <code>limits.max_star</code> is reached.</td></tr></tbody></table><p>Protection materials and temper materials are detected here but never required.</p><h3 id="stage-5-success-rate" tabindex="-1">Stage 5: success rate <a class="header-anchor" href="#stage-5-success-rate" aria-label="Permalink to “Stage 5: success rate”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rate = target-star base rate + effective temper × temper_chance_bonus_per_level</span></span>
<span class="line"><span>final rate = clamp(rate, 0, success_chance_cap)</span></span></code></pre></div><ul><li>The target-star base rate is taken from the recipe <code>success_rates</code> entry for that star; when the recipe does not define one, it falls back to the global <code>success_rates</code> in <code>config.yml</code>.</li><li>Effective temper = <code>clamp(current temper + material temper_boost, 0, max_temper)</code>.</li></ul><h3 id="stages-6-7-event-and-roll" tabindex="-1">Stages 6-7: event and roll <a class="header-anchor" href="#stages-6-7-event-and-roll" aria-label="Permalink to “Stages 6-7: event and roll”">​</a></h3><p><code>StrengthenPreAttemptEvent</code> fires on the main thread. It is cancellable and its success rate can be rewritten with <code>setSuccessRate</code>. A random number in <code>[0, 100)</code> is then drawn; a value below the rate means success.</p><h3 id="stage-8-writing-the-strengthen-layer" tabindex="-1">Stage 8: writing the strengthen layer <a class="header-anchor" href="#stage-8-writing-the-strengthen-layer" aria-label="Permalink to “Stage 8: writing the strengthen layer”">​</a></h3><table tabindex="0"><thead><tr><th>Outcome</th><th>Star</th><th>Temper</th></tr></thead><tbody><tr><td>Success</td><td>Raised to the target star</td><td>Reset to 0</td></tr><tr><td>Failure (target star &lt; 6)</td><td>Unchanged</td><td>Temper gain added</td></tr><tr><td>Failure (target star ≥ 6, no protection)</td><td>Drops 1 star, floor 0</td><td>Temper gain added</td></tr><tr><td>Failure (protection material used)</td><td>Unchanged</td><td>Temper gain added</td></tr></tbody></table><p>Temper gain is +1 when the target star is 8 or below and +2 above 8, then clamped to <code>limits.max_temper</code>.</p><p>Both success and failure update the item&#39;s success count, failure count, and last attempt time; success additionally records first-reach star milestones.</p><h3 id="stages-9-13-charging-actions-and-safe-settlement" tabindex="-1">Stages 9-13: charging, actions, and safe settlement <a class="header-anchor" href="#stages-9-13-charging-actions-and-safe-settlement" aria-label="Permalink to “Stages 9-13: charging, actions, and safe settlement”">​</a></h3><ul><li>Economy costs are charged only after the item rebuild succeeds; a failed charge leaves the attempt uncommitted.</li><li><code>StrengthenAttemptEvent</code> fires during settlement.</li><li>That star&#39;s <code>actions.success</code> / <code>actions.failure</code> receive a mutable <code>item_target</code>, and the final item is read only after the action chain completes.</li><li>Reaching a star in <code>broadcast.local_stars</code> or <code>broadcast.global_stars</code> for the first time sends a broadcast; see <a href="./broadcast.html">Broadcast</a>.</li><li>The final item, unconsumed materials, and other escrow content are settled only on the player&#39;s owner thread, after which the GUI and inventory refresh.</li><li>If material consumption or target rebuild/commit fails, the source restores material amounts and attempts to compensate charged economy. The failed attempt is not committed as a partial result.</li></ul><h3 id="pending-settlement-and-recovery" tabindex="-1">Pending settlement and recovery <a class="header-anchor" href="#pending-settlement-and-recovery" aria-label="Permalink to “Pending settlement and recovery”">​</a></h3><p>A completed result is retained as pending settlement when the player is offline or entity scheduling is rejected. The module does not deliver early or discard escrow:</p><ul><li>A player join retries settlement on that player&#39;s owner thread.</li><li>Opening the strengthen GUI also retries pending settlement.</li><li>Closing the GUI or reloading configuration does not clear committed pending settlement.</li><li>Settlement records completion phases. If the result item was delivered but a later material-return step failed, a retry resumes the remaining phase without delivering the result item again.</li><li>A pending entry is removed only after every settlement phase completes, keeping retries idempotent.</li></ul><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>The pending queue is an in-process recovery mechanism; this page does not claim persistence across a full server restart.</p></div><h2 id="temper" tabindex="-1">Temper <a class="header-anchor" href="#temper" aria-label="Permalink to “Temper”">​</a></h2><p>Temper is a level accumulated on failure that compensates for losing streaks:</p><ul><li>Each failure adds 1 or 2 temper levels depending on the target star, capped at <code>limits.max_temper</code>.</li><li>Each temper level raises the next attempt&#39;s success rate by <code>limits.temper_chance_bonus_per_level</code>.</li><li>Temper resets to 0 after a successful strengthen.</li><li>Materials can define <code>temper_boost</code> to supply extra temper bonus for the current attempt.</li><li>Administrators can clear the main-hand item&#39;s temper with <code>/estrengthen clearcrack</code>.</li></ul><p>Temper state is stored in the strengthen layer PDC.</p><h2 id="milestone-stars" tabindex="-1">Milestone stars <a class="header-anchor" href="#milestone-stars" aria-label="Permalink to “Milestone stars”">​</a></h2><p><code>stars.&lt;star&gt;.name</code> names a star for GUI display. The item state records the set of stars reached for the first time, which prevents duplicate broadcasts.</p><p>At a milestone star you can trigger the following through that star&#39;s <code>effects</code> and <code>actions</code>:</p><ul><li>Extra attributes (<code>ea_attribute</code>) and skill attachment (<code>es_skill</code>).</li><li>Name prefixes or lore markers (<code>name_action</code> / <code>lore_action</code>).</li><li>Success actions such as broadcasts, sounds, and titles.</li></ul><h2 id="action-nodes" tabindex="-1">Action nodes <a class="header-anchor" href="#action-nodes" aria-label="Permalink to “Action nodes”">​</a></h2><p>The <code>actions</code> node of a star stage supports two keys:</p><table tabindex="0"><thead><tr><th>Node</th><th>Trigger</th></tr></thead><tbody><tr><td><code>actions.success</code></td><td>After a successful strengthen at that star.</td></tr><tr><td><code>actions.failure</code></td><td>After a failed strengthen at that star.</td></tr></tbody></table><h3 id="action-example" tabindex="-1">Action example <a class="header-anchor" href="#action-example" aria-label="Permalink to “Action example”">​</a></h3><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">stars</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gold&gt;Damage Boost&lt;/gold&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">      success</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;send_title title=&quot;&lt;gold&gt;&lt;bold&gt;+8 Damage Boost&lt;/bold&gt;&lt;/gold&gt;&quot; subtitle=&quot;&lt;yellow&gt;Bonus damage unlocked&lt;/yellow&gt;&quot;&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;play_sound sound=minecraft:entity.player.levelup volume=1.1 pitch=1.2&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">      failure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;send_message text=&quot;&lt;red&gt;Strengthening failed, currently +%star%.&lt;/red&gt;&quot;&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;play_sound sound=minecraft:block.anvil.destroy volume=1 pitch=0.8&quot;</span></span></code></pre></div><p>See <a href="./placeholders.html">Placeholders</a> for the placeholders available in action lines.</p>`,47)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};